public class SumaMatriz {
    public static void main(String[] args) {
        int[][] matriz = {
            {5, 8, 3, 2},
            {7, 1, 9, 4},
            {6, 3, 8, 5}
        };
        int suma = 0;
        for (int ren = 0; ren < matriz.length; ren++) {
            for (int col = 0; col < matriz[ren].length; col++) {
                suma += matriz[ren][col];
            }
        }
        System.out.println("Total sum: " + suma);
    }
}

