solution:
public class TransponerMatriz {
    public static void main(String[] args) {
        int[][] original = {
            {1, 2, 3},
            {4, 5, 6}
        };
        int filas = original.length;
        int cols = original[0].length;
        int[][] transpuesta = new int[cols][filas];

        for (int ren = 0; ren < filas; ren++) {
            for (int col = 0; col < cols; col++) {
                transpuesta[col][ren] = original[ren][col];
            }
        }

        System.out.println("Original: " + java.util.Arrays.deepToString(original));
        System.out.println("Transpose: " + java.util.Arrays.deepToString(transpuesta));
    }
}
